// Filter out already-processed articles
// We track processed IDs in a static variable or check Google Sheets
const items = $input.all();
const articles = items[0].json.data || items[0].json;

if (!Array.isArray(articles)) {
  return [{ json: { error: 'No articles array found', raw: items[0].json } }];
}

// Get the last 24 hours of articles (4 runs x 6h)
const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);

const newArticles = articles.filter(article => {
  const createdAt = new Date(article.createdAt || article.publishedAt || article.date);
  return createdAt >= cutoff;
});

if (newArticles.length === 0) {
  return [{ json: { skip: true, message: 'No new articles found' } }];
}

return newArticles.map(article => ({
  json: {
    id: article._id || article.id,
    title: article.title,
    content: article.content || article.description || article.summary,
    category: article.category,
    language: article.language || 'ar',
    url: article.url || article.link,
    imageUrl: article.imageUrl || article.image,
    publishedAt: article.createdAt || article.publishedAt || article.date
  }
}));

