parameters.jsCode:
// Parse the GPT-4o JSON response
const raw = $input.first().json;

let content;
try {
  // The response might be in message.content or text
  const text = raw.message?.content || raw.text || raw.output || JSON.stringify(raw);

  // Extract JSON from potential markdown code blocks
  const jsonMatch = text.match(/```json\n?([\s\S]*?)\n?```/) || text.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : text;

  content = JSON.parse(jsonStr);
} catch (e) {
  return [{ json: { error: 'Failed to parse GPT response', raw: raw, parseError: e.message } }];
}

// Flatten for Google Sheets - one row per content piece
const rows = [];
const articleId = content.metadata?.original_article_id || 'unknown';
const generatedAt = content.metadata?.generated_at || new Date().toISOString();

// Twitter thread
content.twitter_thread?.forEach(tweet => {
  rows.push({
    article_id: articleId,
    platform: 'Twitter/X',
    content_type: `Thread Tweet #${tweet.tweet_number}`,
    content_text: tweet.text,
    has_media: tweet.has_media || false,
    notes: '',
    suggested_time: content.metadata?.suggested_posting_times?.twitter || '',
    generated_at: generatedAt,
    status: 'draft'
  });
});

// Instagram carousel
content.instagram_carousel?.forEach(slide => {
  rows.push({
    article_id: articleId,
    platform: 'Instagram',
    content_type: `Carousel Slide #${slide.slide}`,
    content_text: `${slide.headline}\n\n${slide.body}`,
    has_media: true,
    notes: slide.design_notes || '',
    suggested_time: content.metadata?.suggested_posting_times?.instagram || '',
    generated_at: generatedAt,
    status: 'draft'
  });
});

rows.push({
  article_id: articleId,
  platform: 'Instagram',
  content_type: 'Caption',
  content_text: content.instagram_caption || '',
  has_media: false,
  notes: '',
  suggested_time: content.metadata?.suggested_posting_times?.instagram || '',
  generated_at: generatedAt,
  status: 'draft'
});

// LinkedIn
rows.push({
  article_id: articleId,
  platform: 'LinkedIn',
  content_type: 'Post',
  content_text: content.linkedin_post || '',
  has_media: false,
  notes: '',
  suggested_time: content.metadata?.suggested_posting_times?.linkedin || '',
  generated_at: generatedAt,
  status: 'draft'
});

// Facebook
rows.push({
  article_id: articleId,
  platform: 'Facebook',
  content_type: 'Post',
  content_text: content.facebook_post || '',
  has_media: false,
  notes: '',
  suggested_time: content.metadata?.suggested_posting_times?.facebook || '',
  generated_at: generatedAt,
  status: 'draft'
});

// TikTok scripts
content.tiktok_scripts?.forEach(script => {
  rows.push({
    article_id: articleId,
    platform: 'TikTok/Reels',
    content_type: `Script Idea #${script.idea}`,
    content_text: `HOOK: ${script.hook}\n\nSCRIPT: ${script.script}`,
    has_media: true,
    notes: `Sound: ${script.trending_sound_suggestion || 'N/A'}`,
    suggested_time: content.metadata?.suggested_posting_times?.tiktok || '',
    generated_at: generatedAt,
    status: 'draft'
  });
});

// Email newsletter
if (content.email_newsletter) {
  rows.push({
    article_id: articleId,
    platform: 'Email',
    content_type: 'Newsletter Snippet',
    content_text: `Subject: ${content.email_newsletter.subject_line}\nPreview: ${content.email_newsletter.preview_text}\n\n${content.email_newsletter.body_html}\n\nCTA: ${content.email_newsletter.cta_text}`,
    has_media: false,
    notes: '',
    suggested_time: content.metadata?.suggested_posting_times?.email || '',
    generated_at: generatedAt,
    status: 'draft'
  });
}

// Also pass the full content object for the Telegram summary
return rows.map(row => ({ json: { ...row, _fullContent: content } }));

// Build a Telegram summary message
const items = $input.all();
const firstItem = items[0]?.json || {};
const content = firstItem._fullContent || {};
const articleId = firstItem.article_id || 'N/A';

const platformCounts = {};
items.forEach(item => {
  const p = item.json.platform || 'Unknown';
  platformCounts[p] = (platformCounts[p] || 0) + 1;
});

const summary = Object.entries(platformCounts)
  .map(([platform, count]) => `  - ${platform}: ${count} piece(s)`)
  .join('\n');

const message = `🎯 *Darsy Content Repurposing Complete*\n\n` +
  `📰 Article ID: \`${articleId}\`\n` +
  `📊 Generated ${items.length} content pieces:\n${summary}\n\n` +
  `⏰ Suggested posting times (CET):\n` +
  `  - Twitter: ${content.metadata?.suggested_posting_times?.twitter || '10:00 AM'}\n` +
  `  - Instagram: ${content.metadata?.suggested_posting_times?.instagram || '12:00 PM'}\n` +
  `  - LinkedIn: ${content.metadata?.suggested_posting_times?.linkedin || '9:00 AM'}\n` +
  `  - Facebook: ${content.metadata?.suggested_posting_times?.facebook || '6:00 PM'}\n` +
  `  - TikTok: ${content.metadata?.suggested_posting_times?.tiktok || '8:00 PM'}\n` +
  `  - Email: ${content.metadata?.suggested_posting_times?.email || '7:00 AM'}\n\n` +
  `✅ All saved to Google Sheets. Review and approve for publishing.`;

return [{ json: { message } }];

// Gets chatId from Telegram command center webhook, or falls back to env var
const fromWebhook = $input.first().json.body?.chatId;
const chatId = fromWebhook || $env.TELEGRAM_CHAT_ID;
return [{ json: { chatId } }];
